import useCustomizeRouting from '@/hooks/swap/useCustomizeRouting'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { Icon } from '@cetus/ui-kit'
import {
  Box,
  Button,
  FormControl,
  FormLabel,
  HStack,
  Modal,
  ModalBody,
  ModalCloseButton,
  ModalContent,
  ModalFooter,
  ModalHeader,
  ModalOverlay,
  Popover,
  PopoverBody,
  PopoverContent,
  PopoverTrigger,
  Switch,
  Text,
  VStack
} from '@chakra-ui/react'
import { isEqual } from 'lodash'
import { useState } from 'react'
import ConfirmModal from './ConfirmModal'
import List from './List'

interface AggregatorModeProps {
  isOpen: boolean
  onClose(): void
}

const AggregatorModeModal = ({ isOpen, onClose }: AggregatorModeProps) => {
  const { isApp } = useWindowWidth()

  const [confirmModalOpen, setConfirmModalOpen] = useState(false)

  const {
    handleSelectAllProviderClick,
    handleSelectAllDexProviderClick,
    handleSelectAllOtherProviderClick,
    handleProviderClick,
    selectAllProviders,
    selectAllDexProviders,
    otherProviderList,
    selectAllOtherProviders,
    dexProviderList,
    currProvidersSwitchStates,
    providersSwitchStates,
    handleSaveClick
  } = useCustomizeRouting()
  const handleClose = () => {
    if (isEqual(providersSwitchStates, currProvidersSwitchStates)) {
      onClose()
    } else {
      setConfirmModalOpen(true)
    }
  }
  return (
    <>
      <Modal isOpen={isOpen} onClose={handleClose} isCentered>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader fontSize="16px" fontWeight="500">
            Aggregator Settings
          </ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <VStack w="100%">
              <HStack w="100%" justify="space-between" align="flex-end">
                <Box>
                  <HStack>
                    <Text fontSize="14px" color="text_caption">
                      Liquidity Sources
                    </Text>
                    <Popover trigger={isApp ? 'click' : 'hover'}>
                      <PopoverTrigger>
                        <Box as="div">
                          <Icon xlinkHref="#icon-icon_tips" />
                        </Box>
                      </PopoverTrigger>
                      <PopoverContent>
                        <PopoverBody fontSize="12px" color="text_caption">
                          Your trade is routed through one or more of these liquidity sources.
                        </PopoverBody>
                      </PopoverContent>
                    </Popover>
                  </HStack>
                  <Text>Disable/Enable Liquidity Sources</Text>
                </Box>
                <FormControl display="flex" alignItems="center" flex="0 0 108px">
                  <FormLabel htmlFor="select-all" mb="0" mr="8px" fontSize="14px" color="text_paragraph">
                    Select all
                  </FormLabel>
                  <Switch id="select-all" isChecked={!!selectAllProviders} onChange={() => handleSelectAllProviderClick(!selectAllProviders)} />
                </FormControl>
              </HStack>
              <HStack w="100%" bg="bg_primary" p="0 8px 8px" gap="8px" border="1px solid" borderColor="border">
                <List
                  title="Dex"
                  isAllChecked={selectAllDexProviders}
                  onAllSelect={() => handleSelectAllDexProviderClick(!selectAllDexProviders)}
                  onItemSelect={handleProviderClick}
                  list={dexProviderList}
                  checkedMap={currProvidersSwitchStates}
                />
                <List
                  title="Other"
                  isAllChecked={selectAllOtherProviders}
                  onAllSelect={() => handleSelectAllOtherProviderClick(!selectAllOtherProviders)}
                  onItemSelect={handleProviderClick}
                  list={otherProviderList}
                  checkedMap={currProvidersSwitchStates}
                />
              </HStack>
            </VStack>
          </ModalBody>

          <ModalFooter gap="16px">
            <Button flex="1" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button
              flex="1"
              onClick={() => {
                handleSaveClick()
                onClose()
              }}
            >
              Save
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
      {confirmModalOpen && (
        <ConfirmModal
          isOpen={confirmModalOpen}
          onClose={() => {
            setConfirmModalOpen(false)
            onClose()
          }}
          onOk={() => {
            handleSaveClick()
            setConfirmModalOpen(false)
            onClose()
          }}
        />
      )}
    </>
  )
}

export default AggregatorModeModal
