import { AddressCopyLink, MarketSource, MarketType, Ratio } from '@cetus/design'
import useExplorer from '@cetus/hooks/src/useExplorer'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import useTokenPriceStore from '@cetus/stores/src/tokenPrice'
import { CoinInfo } from '@cetus/types'
import { Icon, SingleCoinImage } from '@cetus/ui-kit'
import { Box, HStack, Popover, PopoverBody, PopoverContent, PopoverTrigger, Text, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import PriceChart from './PriceChart'

interface PriceReferenceProps {
  fromCoin?: CoinInfo
  toCoin?: CoinInfo
}

function PriceReference({ fromCoin, toCoin }: PriceReferenceProps) {
  return (
    <VStack w="100%" align="flex-start" gap="20px">
      <HStack justify="flex-start" h="52px">
        <Text fontSize="14px" fontWeight="500" color="text_caption">
          Price Reference
        </Text>
        <Popover trigger="hover">
          <PopoverTrigger>
            <Box>
              <Icon xlinkHref="#icon-icon_tips" />
            </Box>
          </PopoverTrigger>
          <PopoverContent>
            <PopoverBody>
              <Text>
                The following price is only an external reference from 3rd party data providers, which does not reflect actual data on Cetus.
              </Text>
            </PopoverBody>
          </PopoverContent>
        </Popover>
      </HStack>
      <Item coin={fromCoin} />
      <Item coin={toCoin} />
    </VStack>
  )
}

const Item = ({ coin }: { coin?: CoinInfo }) => {
  const navigate = useNavigate()
  const { getExplorerUrl } = useExplorer()
  const { getPriceKline, getTokenPrice } = useTokenPrice()
  const { coinPriceObj } = useTokenPriceStore()
  const [priceData, setPriceData] = useState<{ price: any[]; daily_rate: string }>({ price: [], daily_rate: '' })
  const coinMarketInfo = getTokenPrice(coin?.coin_type as string)
  const fetchPriceData = async (coin_type: string, market: string) => {
    try {
      const data = await getPriceKline(coin_type, market)
      setPriceData(data)
    } catch (error) {
      console.log(error, 'error')
    }
  }

  useEffect(() => {
    if (coinMarketInfo?.base_symbol) {
      fetchPriceData(coinMarketInfo?.base_symbol, coinMarketInfo?.market)
    }
  }, [coinMarketInfo?.base_symbol, coinMarketInfo?.market])

  return (
    <VStack w="100%" gap="20px">
      <HStack w="100%" justify="space-between" align="flex-start" h="32px">
        <HStack>
          <SingleCoinImage imageUrl={coin?.logo_url} w="28px" h="28px" />
          <VStack align="flex-start" gap="4px">
            <Text fontSize="14px" h="16px" lineHeight="16px" color="text_caption">
              {coin?.symbol}
            </Text>
            <Text fontSize="12px" h="12px" lineHeight="12px">
              {coin?.name}
            </Text>
          </VStack>
        </HStack>
        <HStack>
          <MarketSource market={coinMarketInfo?.market as MarketType} />
          <Text color="text_caption" fontSize="14px" fontWeight="500">
            ${coinMarketInfo?.price}
          </Text>
          <Ratio value={priceData?.daily_rate} />
        </HStack>
      </HStack>
      <HStack w="100%" justify="space-between" align="flex-end">
        <AddressCopyLink
          address={coin?.coin_type as string}
          onClickLink={() => navigate(getExplorerUrl(coin?.coin_type, 'coin'))}
          wrapStyle={{ border: '1px solid', borderColor: 'border', h: '24px', borderRadius: '8px', p: '0 8px' }}
        />
        <Box flex="0 0 210px" h="24px" mr="-28px">
          {priceData?.price.length > 0 && <PriceChart data={priceData?.price} />}
        </Box>
      </HStack>
    </VStack>
  )
}

export default PriceReference
