import { CoinInfo } from '@cetus/types'
import { Icon, SingleCoinImage } from '@cetus/ui-kit'
import { d, formatNumber } from '@cetus/utils'
import { Box, Flex, HStack, Spinner, Text, TextProps } from '@chakra-ui/react'
import { useMemo, useState } from 'react'

type CurrentPriceProps = {
  fromToken: CoinInfo
  toToken: CoinInfo
  fromValue?: string
  toValue?: string
  noIcon?: boolean
  noCenter?: boolean
  color?: TextProps['color']
  isLoading?: boolean
  fontSize?: TextProps['fontSize']
}
export default function CurrentPrice(props: CurrentPriceProps) {
  const { fromToken, toToken, fromValue, toValue, noIcon, noCenter, color = 'text_paragraph', isLoading, fontSize = '14px' } = props

  const [direct, setDirect] = useState(true)

  const handleToggleDirect = () => {
    setDirect(direct => !direct)
  }

  const displayPrice = useMemo(() => {
    if (direct && toValue && fromValue) {
      return formatNumber(d(toValue).div(fromValue).toString(), toToken?.decimals)
    }
    if (!direct && toValue && fromValue) {
      return formatNumber(d(fromValue).div(toValue).toString(), fromToken?.decimals)
    }
    return ''
  }, [direct, fromValue, toValue])
  return (
    <Flex alignItems="center" justifyContent={noCenter ? 'space-between' : 'center'}>
      {/* <Skeleton isLoaded={!preSwapLoading}> */}
      <Flex align="center">
        <Flex align="center" whiteSpace="nowrap" cursor="pointer" onClick={handleToggleDirect}>
          {noIcon ? null : direct ? (
            <Box mr="8px">
              <SingleCoinImage imageUrl={fromToken?.logo_url} w="20px" h="20px" />
            </Box>
          ) : (
            <Box mr="8px">
              <SingleCoinImage imageUrl={toToken?.logo_url} w="20px" h="20px" />
            </Box>
          )}
          <HStack>
            <Text color={color} fontSize={fontSize}>
              1
            </Text>
            <Text color={color} fontSize={fontSize}>
              {direct ? fromToken?.symbol : toToken?.symbol}
            </Text>
          </HStack>
          {/* <Text color={usdTextColor}>($0.999)</Text> */}
          <Text>&nbsp;≈&nbsp;</Text>
        </Flex>
        {isLoading ? (
          <Spinner size="sm" />
        ) : (
          // <RefreshLoadingAnimation />
          <Flex align="center" cursor="pointer" onClick={handleToggleDirect}>
            <Text mr="4px" whiteSpace="normal" wordBreak="break-all" color={color} fontSize={fontSize}>
              {displayPrice}
            </Text>
            <Text mr="4px" color={color} fontSize={fontSize}>
              {direct ? toToken?.symbol : fromToken?.symbol}
            </Text>

            {noIcon ? null : direct ? (
              <Box ml="4px" mr="10px">
                <SingleCoinImage imageUrl={toToken?.logo_url} w="20px" h="20px" />
              </Box>
            ) : (
              <Box ml="4px" mr="10px">
                <SingleCoinImage imageUrl={fromToken?.logo_url} w="20px" h="20px" />
              </Box>
            )}
          </Flex>
        )}
      </Flex>
      <Box minW="20p" minH="20px">
        <Icon xlinkHref="#icon-icon_swap1" svgW="16px" svgH="16px" onClick={handleToggleDirect} />
      </Box>
      {/* </Skeleton> */}
    </Flex>
  )
}
