import { usePriceImpact } from '@/hooks/swap/usePriceImpact'
import useSwapStore from '@/store/swap/swap'
import { CurrentPrice } from '@cetus/design'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { CoinInfo } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { Box, HStack, VStack } from '@chakra-ui/react'
import { useState } from 'react'
import PriceImpact from './PriceImpact'

function PriceRatio() {
  const [open, setOpen] = useState(true)
  const { fromCoin, toCoin, fromAmount, toAmount, findRouterLoading } = useSwapStore()
  const { getTokenPrice } = useTokenPrice()

  const { swapPrice, marketPrice, priceImpact, sources, showPriceImpactTips, showPriceImpactWarn } = usePriceImpact(
    fromCoin,
    toCoin,
    fromAmount,
    toAmount
  )
  return (
    <VStack w="100%" p="10px 8px" gap="14px" bg="primary_opacity.10" borderRadius="12px">
      <HStack w="100%" justify="space-between">
        <CurrentPrice
          fromToken={fromCoin as CoinInfo}
          toToken={toCoin as CoinInfo}
          fromValue={fromAmount}
          toValue={toAmount}
          isLoading={findRouterLoading}
          color="text_caption"
        />
        <Box cursor="pointer" onClick={() => setOpen(!open)}>
          <Icon xlinkHref="#icon-icon_arrow" transition="transform 0.5s" transform={open ? 'rotate(180deg)' : 'rotate(0deg)'} fontSize="12px" />
        </Box>
      </HStack>
      {open && (
        <PriceImpact
          fromToken={fromCoin as CoinInfo}
          toToken={toCoin as CoinInfo}
          marketPrice={marketPrice}
          priceImpact={priceImpact}
          sources={sources}
        />
      )}
    </VStack>
  )
}

export default PriceRatio
