import Lock from '@/assets/images/icon_lock@2x.png'
import { AggregatorDex, AggregatorProvider } from '@/types/swap'
import { Icon, SingleCoinImage } from '@cetus/ui-kit'
import { Box, FormControl, FormLabel, HStack, Switch, Text, VStack } from '@chakra-ui/react'
import { useRef, useState } from 'react'
const MAX_CLICK_COUNT = 5
const TIMEOUT = 2000

interface ItemProps {
  item: AggregatorDex
  checkedMap: Partial<Record<AggregatorProvider, boolean>>
  onSelect: (provider: AggregatorProvider, select: boolean) => void
}

const Item = (props: ItemProps) => {
  const { item } = props

  if (item?.subItems) {
    return <ItemWithChildren {...props} />
  }
  if (item?.id === AggregatorProvider?.CETUS) {
    return <CetusItem {...props} />
  }

  return <RegularItem {...props} />
}

const ItemWithChildren = ({ item, checkedMap, onSelect }: ItemProps) => {
  const [open, setOpen] = useState(false)
  return (
    <VStack w="100%">
      <HStack justifyContent="space-between" alignItems="center" w="100%" h="28px" gap="8px">
        <HStack fontSize="14px" gap="12px" color="text_caption" fontWeight="500" onClick={() => setOpen(!open)} cursor="pointer" flex="0 0 125px">
          <SingleCoinImage imageUrl={item?.logo} w="28px" h="28px" />
          <Text>{item?.name}</Text>
          <Box ml="-8px">
            <Icon
              xlinkHref="#icon-icon_arrow"
              fontSize="12px"
              variant="gray"
              transition="transform 0.5s"
              transform={open ? 'rotate(180deg)' : 'rotate(0deg)'}
            />
          </Box>
        </HStack>
        <Switch
          id={item?.id}
          isChecked={item?.subItems?.every(child => !!checkedMap?.[child?.id])}
          onChange={e => {
            if (item?.subItems?.every(child => !!checkedMap?.[child?.id])) {
              item?.subItems?.forEach(child => onSelect(child?.id, false))
            } else {
              item?.subItems?.forEach(child => onSelect(child?.id, true))
            }
          }}
        />
      </HStack>
      {open && (
        <VStack w="100%" border="1px solid" borderColor="border" borderRadius="12px" p="16px 12px" gap="20px">
          {item?.subItems?.map(child => (
            <FormControl key={child.name} display="flex" justifyContent="space-between" alignItems="center" w="100%" h="14px">
              <FormLabel htmlFor={child?.id} mb="0" mr="8px" fontSize="14px" color="text_caption">
                {child?.name}
              </FormLabel>
              <Switch id={child?.id} isChecked={!!checkedMap?.[child?.id]} onChange={() => onSelect(child?.id, !checkedMap?.[child?.id])} />
            </FormControl>
          ))}
        </VStack>
      )}
    </VStack>
  )
}

const CetusItem = ({ item, checkedMap, onSelect }: ItemProps) => {
  const countRef = useRef(0)
  const timer = useRef<any>(null)

  const resetCount = () => {
    if (timer.current) {
      clearTimeout(timer.current)
      countRef.current = 0
    }
  }

  const handleChange = () => {
    countRef.current = countRef.current + 1
    console.log(countRef.current, 'countRef.current')
    if (countRef.current === 1) {
      timer.current = setTimeout(resetCount, TIMEOUT)
    }

    if (countRef.current === MAX_CLICK_COUNT) {
      onSelect(item?.id, !checkedMap?.[item?.id])
      resetCount()
    }
  }
  return (
    <HStack justifyContent="space-between" alignItems="center" w="100%" h="28px">
      <HStack fontSize="14px" gap="12px" color="text_caption" fontWeight="500" flex="0 0 125px">
        <SingleCoinImage imageUrl={item?.logo} w="28px" h="28px" />
        <Text>{item?.name}</Text>
      </HStack>
      <Switch
        id={item?.id}
        isChecked={!!checkedMap?.[item?.id]}
        onChange={handleChange}
        sx={{
          cursor: 'not-allowed',
          span: {
            cursor: 'not-allowed'
          },
          '.chakra-switch__thumb': {
            width: '16px',
            height: '16px',
            background: `center / 12px 12px no-repeat #fff url("${Lock}") !important`
          }
        }}
      />
    </HStack>
  )
}

const RegularItem = ({ item, checkedMap, onSelect }: ItemProps) => {
  return (
    <HStack justifyContent="space-between" alignItems="center" w="100%" h="28px">
      <HStack fontSize="14px" gap="12px" color="text_caption" fontWeight="500" flex="0 0 125px">
        <SingleCoinImage imageUrl={item?.logo} w="28px" h="28px" />
        <Text>{item?.name}</Text>
      </HStack>
      <Switch id={item?.id} isChecked={!!checkedMap?.[item?.id]} onChange={() => onSelect(item?.id, !checkedMap?.[item?.id])} />
    </HStack>
  )
}

export default Item
