import { AggregatorDex, AggregatorProvider } from '@/type/swap-type'
import { FormControl, FormLabel, Switch, VStack } from '@chakra-ui/react'
import Item from './Item'

interface ListProps {
  title: string
  isAllChecked: boolean
  onAllSelect(): void
  onItemSelect: (provider: AggregatorProvider, select: boolean) => void
  list: AggregatorDex[]
  checkedMap: Partial<Record<AggregatorProvider, boolean>>
}
const List = ({ title, isAllChecked, onAllSelect, onItemSelect, list = [], checkedMap = {} }: ListProps) => {
  return (
    <VStack flex="1">
      <FormControl display="flex" justifyContent="space-between" alignItems="center" w="100%" h="46px" p="0 8px">
        <FormLabel htmlFor={title} mb="0" mr="8px" fontSize="14px" color="text_caption" fontWeight="500">
          {title}
        </FormLabel>
        <Switch id={title} onChange={onAllSelect} isChecked={isAllChecked} />
      </FormControl>
      <VStack w="100%" h="310px" overflow="auto" p="8px 8px 0" gap="20px">
        {list?.map(item => {
          return <Item key={item?.name} item={item} checkedMap={checkedMap} onSelect={onItemSelect} />
        })}
      </VStack>
    </VStack>
  )
}

export default List
