import useCustomizeRouting from '@/hooks/swap/useCustomizeRouting'
import useGetRouterConfig from '@/hooks/swap/useGetRouterConfig'
import { Icon } from '@cetus/ui-kit'
import { Button, FormControl, FormLabel, HStack, Popover, PopoverBody, PopoverContent, PopoverTrigger, Skeleton, Switch } from '@chakra-ui/react'
import { useDeepCompareEffect, useRequest } from 'ahooks'
import { useState } from 'react'
import AggregatorModeModal from './AggregatorModal'

function AggregatorMode() {
  const [settingOpen, setSettingOpen] = useState(false)
  const onClose = () => {
    setSettingOpen(false)
  }

  const { fetchRouterConfig } = useGetRouterConfig()

  const { loading } = useRequest(fetchRouterConfig)

  const { handleSelectAllProviderClick, handleSaveClick, currProvidersSwitchStates, isOpenAggregatorMode } = useCustomizeRouting()

  const handleChange = () => {
    handleSelectAllProviderClick(!isOpenAggregatorMode)
  }

  useDeepCompareEffect(() => {
    handleSaveClick()
  }, [currProvidersSwitchStates])

  return (
    <>
      <Skeleton isLoaded={!loading} w="190px" h="28px">
        <HStack border="1px solid" borderColor="border" borderRadius="8px" h="28px" bg="bg_secondary">
          <Popover trigger="hover">
            <PopoverTrigger>
              <FormControl display="flex" alignItems="center" pl="8px">
                <FormLabel
                  htmlFor="aggregator-mode"
                  mb="0"
                  bg="plus_mode_color"
                  color="transparent"
                  backgroundClip="text"
                  fontSize="12px"
                  fontWeight="500"
                  fontStyle="normal"
                >
                  Aggregator Mode
                </FormLabel>
                <Switch id="aggregator-mode" isChecked={isOpenAggregatorMode} onChange={handleChange} />
              </FormControl>
            </PopoverTrigger>
            <PopoverContent>
              <PopoverBody fontSize="12px" color="text_caption">
                The Aggregator Mode will aggregate external liquidity sources
              </PopoverBody>
            </PopoverContent>
          </Popover>
          <Button
            variant="unstyled"
            minW="20px"
            w="20px"
            p="7px 4px"
            h="26px"
            bg="border"
            borderRadius="0 8px 8px 0"
            onClick={() => setSettingOpen(!settingOpen)}
          >
            <Icon xlinkHref="#icon-icon_list_token" fontSize="12px" />
          </Button>
        </HStack>
      </Skeleton>

      {settingOpen && <AggregatorModeModal isOpen={settingOpen} onClose={onClose} />}
    </>
  )
}

export default AggregatorMode
