import { HTextLabelBox, Icon, SingleCoinImage } from '@cetus/ui-kit'
import { Center, Divider, HStack, Text, VStack } from '@chakra-ui/react'

export interface TradeConfirmAmountInfoProps {
  coinA?: AmountInfoProps
  coinB?: AmountInfoProps
  icon?: string
}
/**
 * 交易确认 展示 amount 信息弹窗
 * @param param0
 * @returns
 */
function TradeConfirmAmountInfo({ coinA, coinB, icon }: TradeConfirmAmountInfoProps) {
  return (
    <VStack w="100%" bg="bg_primary" borderRadius="8px" border="1px solid" borderColor="border" position="relative">
      {coinA && (
        <VStack w="100%" h="90px" pl="16px" pr="16px" justifyContent="center">
          <AmountInfo {...coinA} />
        </VStack>
      )}
      <Divider borderColor="border" />
      {coinB && (
        <VStack w="100%" h="90px" pl="16px" pr="16px" justifyContent="center">
          <AmountInfo {...coinB} />
        </VStack>
      )}

      <Center
        w="36px"
        h="36px"
        borderRadius="50%"
        position="absolute"
        top="calc(50% - 18px)"
        right="20px"
        border="2px solid"
        borderColor="border"
        boxShadow="trade_icon_shadow"
        bg="input_bg"
      >
        {icon && <Icon xlinkHref={icon} svgFill="text_caption" fontSize="12px" />}
      </Center>
    </VStack>
  )
}

type AmountInfoProps = {
  amount: string
  logo: string
  symbol?: string
}

function AmountInfo({ amount, logo, symbol }: AmountInfoProps) {
  return (
    <HTextLabelBox
      leftLabel={amount}
      leftLabelFontSize="28px"
      leftLabelColor="text_caption"
      rightValue={
        <HStack gap="8px" justifyContent="end">
          <SingleCoinImage imageUrl={logo} />
          {symbol && <Text color="text_caption">{symbol}</Text>}
        </HStack>
      }
    />
  )
}

export default TradeConfirmAmountInfo
