import useCustomizeRouting from '@/hooks/swap/useCustomizeRouting'
import { useSwapHook } from '@/hooks/swap/useSwap'
import { useSwapButtonStatus } from '@/hooks/swap/useSwapButtonStatus'
import useSwapStore from '@/store/swap/swap'
import { TradeInputGroup } from '@cetus/design'
import { useAccountBalance, useInterval } from '@cetus/hooks'
import { useAccountStore } from '@cetus/stores'
import { HTextLabelBox } from '@cetus/ui-kit'
import { Button, HStack, VStack } from '@chakra-ui/react'
import { useState } from 'react'
import SwapConfirmModel from '../modal/SwapConfirmModel'
import AggregatorMode from './AggregatorMode'
import PriceRatio from './PriceRatio'
import PriceReference from './PriceReference'
import Slippage from './Slippage'
import SwapRoutes from './SwapRoutes'

interface SwapProps {}
function Swap({}: SwapProps) {
  const { fromCoin, toCoin, byAmountIn, findRouterLoading } = useSwapStore()
  const {
    handleSelectToken,
    handleAmountChange,
    fromAmount,
    toAmount,
    fromAmountValue,
    toAmountValue,
    fromBalanceInfo,
    toBalanceInfo,
    amountLimit,
    getSwapSecondaryData,
    doSwapAction,
    reCalculateRouteData
  } = useSwapHook()
  const { currentAccount, onWalletModal } = useAccountStore()
  const [slippage, setSlippage] = useState<{ value: number; isOpen: boolean }>({ value: 0.5, isOpen: false })

  const { fetchAccountBalance } = useAccountBalance()

  // Swap 按钮状态
  const { btnText, btnDisabled } = useSwapButtonStatus(fromBalanceInfo?.balanceFormat)
  const [isOpenConfirmModel, setIsOpenConfirmModel] = useState<boolean>(false)

  const { isOpenAggregatorMode } = useCustomizeRouting()

  useInterval({
    interval: 20 * 1000,
    callback: () => {
      //刷新Router
      reCalculateRouteData()
      //刷新余额
      fetchAccountBalance()
    }
  })

  const onSlippageVisible = () => {
    setSlippage(pre => ({ ...pre, isOpen: !pre.isOpen }))
  }
  return (
    <>
      <VStack gap="16px">
        <HStack w="100%" justify="space-between">
          <AggregatorMode />
          <HStack>
            <Slippage
              isOpen={slippage.isOpen}
              value={slippage.value}
              onChange={value => setSlippage(pre => ({ ...pre, value }))}
              onClose={() => setSlippage(pre => ({ ...pre, isOpen: false }))}
              onSlippageVisible={onSlippageVisible}
            />
          </HStack>
        </HStack>
        <TradeInputGroup
          icon="#icon-a-icon_trade"
          onClick={() => {}}
          from={{
            title: 'You Pay',
            balance: fromBalanceInfo?.balanceDisplay || '',
            value: fromAmount,
            amountValue: fromAmountValue,
            loading: !byAmountIn && findRouterLoading,
            onChange: value => {
              handleAmountChange(value, true)
            },
            selectable: true,
            placeholder: '0.0',
            token: fromCoin,
            onFocusChange: (focus: boolean) => {},
            onTokenChange: (token: any) => {
              handleSelectToken(token, true)
            },
            handleHalfBalance: () => {},
            handleMaxBalance: () => {}
          }}
          to={{
            title: 'You Receive',
            balance: toBalanceInfo?.balanceDisplay || '',
            value: toAmount,
            amountValue: toAmountValue,
            loading: byAmountIn && findRouterLoading,
            onFocusChange: (focus: boolean) => {},
            onTokenChange: (token: any) => {
              handleSelectToken(token, false)
            },
            inputAllowed: !isOpenAggregatorMode,
            onChange: value => {
              handleAmountChange(value, false)
            },
            selectable: true,
            placeholder: '0.0',
            token: toCoin
          }}
        />
        <VStack p="0 8px 16px" w="100%" gap="16px" border="1px solid" borderColor="border" borderRadius="20px" bg="bg_secondary">
          <Button
            w="calc(100% + 18px)"
            h="52px"
            margin="-1px -1px 0"
            fontSize="18px"
            fontWeight="600"
            borderRadius="16px"
            isDisabled={findRouterLoading || btnDisabled}
            isLoading={findRouterLoading}
            onClick={() => {
              if (currentAccount) {
                setIsOpenConfirmModel(true)
              } else {
                onWalletModal(true)
              }
            }}
          >
            {btnText}
          </Button>
          {!!+fromAmount && !!+toAmount && (
            <>
              <PriceRatio />
              <HTextLabelBox
                leftLabel={byAmountIn ? 'Minimum Received' : 'Maximum Sold'}
                rightValue={`${amountLimit} ${byAmountIn ? toCoin?.symbol : fromCoin?.symbol}`}
                leftLabelFontSize="14px"
                rightValueFontSize="14px"
                labelStyle={{ fontWeight: 500 }}
                valueStyle={{ fontWeight: 500 }}
                wrapStyle={{
                  p: '0 8px'
                }}
              />

              <SwapRoutes />
            </>
          )}
        </VStack>
        <PriceReference fromCoin={fromCoin} toCoin={toCoin} />

        {/* 交易确认弹窗 */}
        {isOpenConfirmModel && (
          <SwapConfirmModel
            data={getSwapSecondaryData()}
            isOpen={isOpenConfirmModel}
            onSubmitClick={doSwapAction}
            onClose={() => {
              setIsOpenConfirmModel(false)
            }}
          />
        )}
      </VStack>
    </>
  )
}

export default Swap
