import { formatTime } from '@/utils/api-data-utils'
import { symbolDataDisplayProcessing } from '@cetus/utils'
import { Line, LineChart, ResponsiveContainer, Tooltip } from 'recharts'
import { CategoricalChartProps } from 'recharts/types/chart/generateCategoricalChart'

// 自定义 Tooltip 内容
const CustomTooltip = ({ active, payload, label }: any) => {
  console.log('🚀 ~ file: PriceChart.tsx:40 ~ CustomTooltip ~ payload:', payload)
  if (active && payload && payload.length) {
    return (
      <div
        style={{
          backgroundColor: '#121212',
          border: '1px solid #23252C',
          padding: '12px',
          borderRadius: '8px',
          position: 'relative',
          left: '0px', // 控制位置
          top: '-30px', // 控制位置
          fontSize: '12px'
        }}
      >
        <p style={{ color: '#909CA4' }}>{formatTime(payload[0]?.payload?.timestamp)}</p>
        <p style={{ color: '#fff', marginTop: '8px' }}>{symbolDataDisplayProcessing(payload[0].value, '$')}</p>
      </div>
    )
  }
  return null
}

export default function PriceChart({ data }: { data: CategoricalChartProps['data'] }) {
  return (
    <ResponsiveContainer width="100%" height="100%">
      <LineChart
        width={500}
        height={300}
        data={data}
        margin={{
          top: 5,
          right: 30,
          left: 20,
          bottom: 5
        }}
      >
        <defs>
          <linearGradient id="priceLine" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="rgba(117, 200, 255, 1)" />
            <stop offset="100%" stopColor="rgba(104, 255, 216, 1)" />
          </linearGradient>
        </defs>
        <Tooltip cursor={false} content={<CustomTooltip />} />
        <Line dot={false} dataKey="price" stroke="url(#priceLine)" />
      </LineChart>
    </ResponsiveContainer>
  )
}
